{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from stdin, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import * as readline from 'readline'
import { parseSheet } from './parser.js'
import { evaluateSheet, getDependencies } from './evaluator.js'

async function main() {
  const args = process.argv.slice(2)

  // Check arguments
  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read input
  const rl = readline.createInterface({
    input: process.stdin,
    crlfDelay: Infinity
  })

  const lines = []
  for await (const line of rl) {
    lines.push(line)
  }

  // Parse the sheet
  let sheet
  try {
    sheet = parseSheet(lines)
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }

  // Evaluate or get dependencies
  let result
  try {
    if (mode === 'values') {
      result = evaluateSheet(sheet)
    } else {
      result = getDependencies(sheet)
    }
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }

  // Output
  for (const line of result) {
    process.stdout.write(line + '\n')
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write('error: ' + err.message + '\n')
  process.exit(2)
})
"}

