{"file_path":"src/parser.js","content":"/**
 * Parser for the spreadsheet format and formulas.
 */

/**
 * Converts a column name to a number (A=1, Z=26, AA=27, etc.)
 */
function colToNum(col) {
  let num = 0
  for (let i = 0; i < col.length; i++) {
    num = num * 26 + (col.charCodeAt(i) - 'A'.charCodeAt(0) + 1)
  }
  return num
}

/**
 * Checks if a column number is valid (1-702 for A-ZZ)
 */
function isValidCol(num) {
  return num >= 1 && num <= 702
}

/**
 * Checks if a row number is valid (1-999)
 */
function isValidRow(num) {
  return num >= 1 && num <= 999
}

/**
 * Parses and validates a cell address like "A1" or "AA99"
 * Returns { col, row, colName, rowNum } or throws
 */
function parseAddress(addr) {
  const match = addr.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) {
    return null
  }

  const colName = match[1]
  const rowNum = parseInt(match[2], 10)

  const colNum = colToNum(colName)

  if (!isValidCol(colNum) || !isValidRow(rowNum)) {
    return null
  }

  return { col: colNum, row: rowNum, colName, rowNum }
}

/**
 * Parses a sheet from an array of input lines
 * Returns { cells: Map<address => {addr, content, isFormula}> }
 */
export function parseSheet(lines) {
  const cells = new Map() // Map from "A1" => { content, isFormula }
  const seen = new Set()

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    const lineNumber = lineNum + 1

    // Strip leading spaces/tabs
    let stripped = line.replace(/^[ \t]+/, '')

    // Ignore empty lines and comments
    if (!stripped || stripped[0] === '#') {
      continue
    }

    // Find the address
    const parts = stripped.split(/[ \t]+/)
    const addrStr = parts[0].toUpperCase()
    const addressInfo = parseAddress(addrStr)

    if (!addressInfo) {
      throw new Error(`error: line ${lineNumber}: invalid cell address ${addrStr}`)
    }

    // Check for duplicate
    if (seen.has(addrStr)) {
      throw new Error(`error: line ${lineNumber}: cell ${addrStr} is declared twice`)
    }
    seen.add(addrStr)

    // Find the content (everything after the first run of whitespace)
    const contentStart = line.indexOf(addrStr) + addrStr.length
    let content = line.substring(contentStart).replace(/^[ \t]+/, '')

    // Determine if it's a formula
    const isFormula = content.startsWith('=')

    cells.set(addrStr, {
      addr: addressInfo,
      content,
      isFormula,
      addrStr
    })
  }

  return { cells }
}

/**
 * Lexer for formulas
 */
class Lexer {
  constructor(input) {
    this.input = input
    this.pos = 0
  }

  skipWhitespace() {
    while (this.pos < this.input.length && /[ \t]/.test(this.input[this.pos])) {
      this.pos++
    }
  }

  peek() {
    this.skipWhitespace()
    if (this.pos >= this.input.length) return null
    return this.input[this.pos]
  }

  peekChar(n) {
    this.skipWhitespace()
    if (this.pos + n >= this.input.length) return null
    return this.input[this.pos + n]
  }

  next() {
    this.skipWhitespace()
    if (this.pos >= this.input.length) return null

    const ch = this.input[this.pos]

    // Numbers
    if (/\d/.test(ch)) {
      let num = ''
      while (this.pos < this.input.length && /[\d.]/.test(this.input[this.pos])) {
        num += this.input[this.pos]
        this.pos++
      }
      return { type: 'number', value: num }
    }

    // Letters (keywords, addresses, functions)
    if (/[A-Za-z]/.test(ch)) {
      let word = ''
      while (this.pos < this.input.length && /[A-Za-z0-9]/.test(this.input[this.pos])) {
        word += this.input[this.pos]
        this.pos++
      }
      word = word.toUpperCase()

      // Check if it's a valid address
      const addr = parseAddress(word)
      if (addr) {
        return { type: 'address', value: word, addr }
      }

      // Keywords
      if (word === 'TRUE') return { type: 'true', value: true }
      if (word === 'FALSE') return { type: 'false', value: false }

      // Function or name
      return { type: 'name', value: word }
    }

    // Operators and delimiters
    if (ch === '(') {
      this.pos++
      return { type: 'lparen' }
    }
    if (ch === ')') {
      this.pos++
      return { type: 'rparen' }
    }
    if (ch === ',') {
      this.pos++
      return { type: 'comma' }
    }
    if (ch === ':') {
      this.pos++
      return { type: 'colon' }
    }
    if (ch === '^') {
      this.pos++
      return { type: 'power' }
    }
    if (ch === '*') {
      this.pos++
      return { type: 'mult' }
    }
    if (ch === '/') {
      this.pos++
      return { type: 'div' }
    }
    if (ch === '+') {
      this.pos++
      return { type: 'plus' }
    }
    if (ch === '-') {
      this.pos++
      return { type: 'minus' }
    }
    if (ch === '<') {
      this.pos++
      if (this.peek() === '=') {
        this.pos++
        return { type: 'lte' }
      } else if (this.peek() === '>') {
        this.pos++
        return { type: 'ne' }
      }
      return { type: 'lt' }
    }
    if (ch === '>') {
      this.pos++
      if (this.peek() === '=') {
        this.pos++
        return { type: 'gte' }
      }
      return { type: 'gt' }
    }
    if (ch === '=') {
      this.pos++
      return { type: 'eq' }
    }

    // Unknown character
    throw new Error('Unexpected character: ' + ch)
  }
}

/**
 * Parser for formulas
 */
class Parser {
  constructor(formula) {
    this.lexer = new Lexer(formula)
    this.current = this.lexer.next()
    this.referencedAddresses = []
  }

  peek() {
    return this.current
  }

  consume(expectedType) {
    const token = this.current
    this.current = this.lexer.next()
    return token
  }

  parseFormula() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()

    while (
      this.current &&
      ['eq', 'ne', 'lt', 'lte', 'gt', 'gte'].includes(this.current.type)
    ) {
      const op = this.consume().type
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()

    while (this.current && ['plus', 'minus'].includes(this.current.type)) {
      const op = this.consume().type
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()

    while (this.current && ['mult', 'div'].includes(this.current.type)) {
      const op = this.consume().type
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parsePower() {
    let left = this.parseUnary()

    if (this.current && this.current.type === 'power') {
      this.consume()
      const right = this.parsePower() // Right associative
      return { type: 'binop', op: 'power', left, right }
    }

    return left
  }

  parseUnary() {
    if (this.current && ['plus', 'minus'].includes(this.current.type)) {
      const op = this.consume().type
      const expr = this.parseUnary()
      return { type: 'unop', op, expr }
    }

    return this.parsePrimary()
  }

  parsePrimary() {
    if (!this.current) {
      throw new Error('Unexpected end of input')
    }

    // Parentheses
    if (this.current.type === 'lparen') {
      this.consume()
      const expr = this.parseFormula()
      if (!this.current || this.current.type !== 'rparen') {
        throw new Error('Expected )')
      }
      this.consume()
      return expr
    }

    // Number
    if (this.current.type === 'number') {
      const token = this.consume()
      return { type: 'number', value: token.value }
    }

    // TRUE/FALSE
    if (this.current.type === 'true') {
      this.consume()
      return { type: 'true' }
    }
    if (this.current.type === 'false') {
      this.consume()
      return { type: 'false' }
    }

    // Address or Range or Function
    if (this.current.type === 'address') {
      const addr = this.consume()
      this.referencedAddresses.push(addr.value)

      // Check for range
      if (this.current && this.current.type === 'colon') {
        this.consume()
        if (!this.current || this.current.type !== 'address') {
          throw new Error('Expected address after :')
        }
        const endAddr = this.consume()
        this.referencedAddresses.push(endAddr.value)
        return {
          type: 'range',
          start: addr.value,
          end: endAddr.value
        }
      }

      return { type: 'address', value: addr.value }
    }

    // Function or Name
    if (this.current.type === 'name') {
      const name = this.consume()
      if (!this.current || this.current.type !== 'lparen') {
        throw new Error('Expected ( after function name')
      }
      this.consume()

      const args = []
      if (!this.current || this.current.type !== 'rparen') {
        args.push(this.parseArgument())
        while (this.current && this.current.type === 'comma') {
          this.consume()
          args.push(this.parseArgument())
        }
      }

      if (!this.current || this.current.type !== 'rparen') {
        throw new Error('Expected )')
      }
      this.consume()

      return { type: 'call', name: name.value, args }
    }

    throw new Error('Unexpected token: ' + this.current.type)
  }

  parseArgument() {
    // Arguments can be ranges or expressions
    let expr = this.parseComparison()

    // Check if this is a range (must be directly address:address)
    if (this.current && this.current.type === 'colon') {
      if (expr.type !== 'address') {
        throw new Error('Range must start with address')
      }
      this.consume()
      if (!this.current || this.current.type !== 'address') {
        throw new Error('Expected address after :')
      }
      const endAddr = this.consume()
      return {
        type: 'range',
        start: expr.value,
        end: endAddr.value
      }
    }

    return expr
  }
}

/**
 * Parses a formula and returns the AST
 */
export function parseFormula(content) {
  if (!content.startsWith('=')) {
    return null
  }

  const formulaBody = content.substring(1)
  if (!formulaBody) {
    return null
  }

  try {
    const parser = new Parser(formulaBody)
    const ast = parser.parseFormula()

    if (parser.current !== null) {
      throw new Error('Unexpected tokens after formula')
    }

    return ast
  } catch (err) {
    return null // Invalid formula syntax
  }
}

/**
 * Extracts all referenced addresses from a parsed formula AST
 */
export function extractAddresses(ast) {
  if (!ast) return []

  const addresses = []

  function visit(node) {
    if (!node) return

    if (node.type === 'address') {
      addresses.push(node.value)
    } else if (node.type === 'range') {
      addresses.push(node.start)
      addresses.push(node.end)
    } else if (node.type === 'binop') {
      visit(node.left)
      visit(node.right)
    } else if (node.type === 'unop') {
      visit(node.expr)
    } else if (node.type === 'call') {
      for (const arg of node.args) {
        visit(arg)
      }
    }
  }

  visit(ast)
  return addresses
}
"}

