      if (this.current && this.current.type === 'colon') {
        this.consume()
        if (!this.current || this.current.type !== 'address') {
          throw new Error('Expected address after :')
        }
        const endAddr = this.consume()
        this.referencedAddresses.push(endAddr.value)
        return {
          type: 'range',
          start: addr.value,
          end: endAddr.value
        }
      }

      return { type: 'address', value: addr.value }
    }

    // Function or Name
    if (this.current.type === 'name') {
      const name = this.consume()
      if (!this.current || this.current.type !== 'lparen') {
        throw new Error('Expected ( after function name')
      }
      this.consume()

      const args = []
      if (!this.current || this.current.type !== 'rparen') {
        args.push(this.parseArgument())
        while (this.current && this.current.type === 'comma') {
          this.consume()
          args.push(this.parseArgument())
        }
      }

      if (!this.current || this.current.type !== 'rparen') {
        throw new Error('Expected )')
      }
      this.consume()

      return { type: 'call', name: name.value, args }
    }

