      }
      this.consume()
      if (!this.current || this.current.type !== 'address') {
        throw new Error('Expected address after :')
      }
      const endAddr = this.consume()
      return {
        type: 'range',
        start: expr.value,
        end: endAddr.value
      }
    }

    return expr
  }
}

/**
 * Parses a formula and returns the AST
 */
export function parseFormula(content) {
  if (!content.startsWith('=')) {
    return null
  }

  const formulaBody = content.substring(1)
  if (!formulaBody) {
    return null
  }

  try {
    const parser = new Parser(formulaBody)
    const ast = parser.parseFormula()

    if (parser.current !== null) {
      throw new Error('Unexpected tokens after formula')
    }

    return ast
  } catch (err) {
    return null // Invalid formula syntax
  }
}

/**
 * Extracts all referenced addresses from a parsed formula AST
 */
export function extractAddresses(ast) {
  if (!ast) return []

  const addresses = []

  function visit(node) {
    if (!node) return

    if (node.type === 'address') {
      addresses.push(node.value)
    } else if (node.type === 'range') {
      addresses.push(node.start)
      addresses.push(node.end)
    } else if (node.type === 'binop') {
      visit(node.left)
      visit(node.right)
    } else if (node.type === 'unop') {
      visit(node.expr)
    } else if (node.type === 'call') {
      for (const arg of node.args) {
        visit(arg)
      }
    }
  }

  visit(ast)
  return addresses
}
