  evaluating.delete(addrStr)

  // Cache result
  evaluated.set(addrStr, result)
  return result
}

/**
 * Evaluates all cells in a sheet and returns formatted output
 */
export function evaluateSheet(sheet) {
  const evaluated = new Map()
  const evaluating = new Set()

  // Sort cells by column then row
  const sorted = Array.from(sheet.cells.entries()).sort((a, b) => {
    const addrA = a[1].addr
    const addrB = b[1].addr
    if (addrA.col !== addrB.col) {
      return addrA.col - addrB.col
    }
    return addrA.row - addrB.row
  })

  const output = []
  for (const [addrStr, cell] of sorted) {
    const value = evaluateCell(addrStr, sheet, evaluated, evaluating)
    output.push(`${addrStr}=${formatValue(value)}`)
  }

  return output
}

/**
 * Gets dependencies for all cells
 */
export function getDependencies(sheet) {
  const output = []

  // Sort cells by column then row
  const sorted = Array.from(sheet.cells.entries()).sort((a, b) => {
    const addrA = a[1].addr
    const addrB = b[1].addr
    if (addrA.col !== addrB.col) {
      return addrA.col - addrB.col
    }
    return addrA.row - addrB.row
  })

  for (const [addrStr, cell] of sorted) {
    let deps = []

    if (cell.isFormula) {
      const ast = parseFormula(cell.content)
      if (ast !== null) {
        deps = extractAddresses(ast)

        // Filter to only valid addresses and remove duplicates
        const validDeps = new Set()
        for (const dep of deps) {
          const depInfo = parseAddress(dep)
          if (depInfo) {
            validDeps.add(dep)
          }
        }

        // Sort deps by column then row
        deps = Array.from(validDeps).sort((a, b) => {
          const addrA = parseAddress(a)
          const addrB = parseAddress(b)
          if (addrA.col !== addrB.col) {
            return addrA.col - addrB.col
          }
          return addrA.row - addrB.row
        })
      }
    }

    if (deps.length > 0) {
      output.push(`${addrStr}: ${deps.join(' ')}`)
    } else {
      output.push(`${addrStr}:`)
    }
  }

  return output
}
