  const aIsNum = typeof a === 'number'
  const aIsText = typeof a === 'string' && !isError(a)
  const aIsBool = typeof a === 'boolean'

  const bIsNum = typeof b === 'number'
  const bIsText = typeof b === 'string' && !isError(b)
  const bIsBool = typeof b === 'boolean'

