  if (aIsNum && bIsNum) return { cmp: (a < b ? -1 : a > b ? 1 : 0), compatible: true }
  if (aIsText && bIsText) return { cmp: (a < b ? -1 : a > b ? 1 : 0), compatible: true }
  if (aIsBool && bIsBool) return { cmp: (a === false && b === true ? -1 : a === true && b === false ? 1 : 0), compatible: true }

