/**
 * Sheet and formula parsing.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

function colToNum(col) {
  let num = 0
  for (let i = 0; i < col.length; i++) {
    num = num * 26 + (col.charCodeAt(i) - 65 + 1)
  }
  return num
}

export function numToCol(num) {
  let s = ''
  let c = num
  while (c > 0) {
    const rem = (c - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    c = Math.floor((c - 1) / 26)
  }
  return s
}

/**
 * Parses a (already upper-cased) cell address. Returns { col, row } or null
 * when the address lies outside the addressable range.
 */
export function parseAddress(addr) {
  const m = ADDRESS_RE.exec(addr)
  if (!m) return null
  const col = colToNum(m[1])
  const row = parseInt(m[2], 10)
  if (col < 1 || col > 702) return null
  if (row < 1) return null
  return { col, row }
}

export class SheetError extends Error {}

/**
 * Parses the sheet source text into a map of address -> { content, col, row }.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    const m = /^([^ \t]+)(?:[ \t]+([\s\S]*))?$/.exec(stripped)
    const addrStr = m[1].toUpperCase()
    const content = m[2] === undefined ? '' : m[2]

    const addr = parseAddress(addrStr)
    if (!addr) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrStr}`)
    }
    if (cells.has(addrStr)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addrStr} is declared twice`)
    }
    cells.set(addrStr, { content, col: addr.col, row: addr.row })
  }

  return cells
}

/* ------------------------------------------------------------------ */
/* Formula lexer                                                       */
/* ------------------------------------------------------------------ */

class LexError extends Error {}

function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }

    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      const text = m[0]
      i += text.length
      const next = src[i]
      if (next !== undefined && /[0-9.A-Za-z]/.test(next)) throw new LexError('bad number')
      tokens.push({ type: 'number', value: parseFloat(text) })
      continue
    }

    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i))
      const word = m[0]
      i += word.length
      tokens.push({ type: 'word', value: word.toUpperCase() })
      continue
    }

    const two = src.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: two })
      i += 2
      continue
    }

    if ('^*/+-=<>(),:'.includes(ch)) {
      tokens.push({ type: ch })
      i++
      continue
    }

    throw new LexError('unexpected character')
  }
  return tokens
}

/* ------------------------------------------------------------------ */
/* Formula parser                                                      */
/* ------------------------------------------------------------------ */

const COMPARISONS = new Set(['=', '<>', '<', '<=', '>', '>='])

class FormulaParser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new LexError('expected ' + type)
    this.pos++
    return t
  }

  parseExpression() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
      if (!t || !COMPARISONS.has(t.type)) break
      this.next()
      const right = this.parseAdditive()
      left = { type: 'binop', op: t.type, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    for (;;) {
      const t = this.peek()
      if (!t || (t.type !== '+' && t.type !== '-')) break
      this.next()
      const right = this.parseMultiplicative()
      left = { type: 'binop', op: t.type, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    for (;;) {
      const t = this.peek()
      if (!t || (t.type !== '*' && t.type !== '/')) break
      this.next()
      const right = this.parsePower()
      left = { type: 'binop', op: t.type, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    const t = this.peek()
    if (t && t.type === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && (t.type === '+' || t.type === '-')) {
      this.next()
      const operand = this.parseUnary()
      return { type: 'unop', op: t.type, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new LexError('unexpected end')

    if (t.type === 'number') {
      this.next()
      return { type: 'number', value: t.value }
    }

    if (t.type === '(') {
      this.next()
      const inner = this.parseExpression()
      this.expect(')')
      // A range that is not written directly as a function argument.
      if (inner.type === 'range') {
        return { type: 'range', start: inner.start, end: inner.end, misplaced: true }
      }
      return inner
    }

    if (t.type === 'word') {
      this.next()
      const nxt = this.peek()
      if (nxt && nxt.type === '(') {
        this.next()
        const args = []
        if (this.peek() && this.peek().type === ')') {
          this.next()
        } else {
          args.push(this.parseArgument())
          while (this.peek() && this.peek().type === ',') {
            this.next()
            args.push(this.parseArgument())
          }
          this.expect(')')
        }
        return { type: 'call', name: t.value, args }
      }
      if (t.value === 'TRUE') return { type: 'boolean', value: true }
      if (t.value === 'FALSE') return { type: 'boolean', value: false }

      // A word read as a cell address; possibly outside the addressable range.
      const ref = { type: 'ref', name: t.value }
      const colon = this.peek()
      if (colon && colon.type === ':') {
        this.next()
        const endTok = this.peek()
        if (!endTok || endTok.type !== 'word') throw new LexError('expected address')
        this.next()
        if (endTok.value === 'TRUE' || endTok.value === 'FALSE') {
          throw new LexError('bad range end')
        }
        return { type: 'range', start: t.value, end: endTok.value }
      }
      return ref
    }

