/**
 * Evaluator for formulas and cells.
 */

import { parseFormula, extractAddresses, parseAddress } from './parser.js'

const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/**
 * Checks if a value is an error
 */
function isError(val) {
  return typeof val === 'string' && ERROR_TOKENS.includes(val)
}

/**
 * Checks if a string is a valid number literal
 */
function isNumberLiteral(str) {
  if (!str) return false
  const match = str.match(/^-?(\d+\.?\d*|\d*\.\d+)$/)
  return match !== null
}

/**
 * Parses a literal value
 */
function parseLiteral(content) {
  if (!content) {
    return 0
  }

  if (ERROR_TOKENS.includes(content)) {
    return content
  }

  if (content === 'TRUE') {
    return true
  }

  if (content === 'FALSE') {
    return false
  }

  if (isNumberLiteral(content)) {
    return parseFloat(content)
  }

  return content
}

/**
 * Converts a value to a number (for arithmetic operations)
 */
function toNumber(val) {
  if (typeof val === 'number') return val
  if (typeof val === 'boolean') return val ? 1 : 0
  if (isError(val)) return val
  return '#VALUE!'
}

/**
 * Converts two values for comparison
 */
function compareValues(a, b) {
  // Determine types
  const aIsNum = typeof a === 'number'
  const aIsText = typeof a === 'string' && !isError(a)
  const aIsBool = typeof a === 'boolean'

  const bIsNum = typeof b === 'number'
  const bIsText = typeof b === 'string' && !isError(b)
  const bIsBool = typeof b === 'boolean'

  // Numbers < Texts < Booleans
  if (aIsNum && bIsNum) return { cmp: (a < b ? -1 : a > b ? 1 : 0), compatible: true }
  if (aIsText && bIsText) return { cmp: (a < b ? -1 : a > b ? 1 : 0), compatible: true }
  if (aIsBool && bIsBool) return { cmp: (a === false && b === true ? -1 : a === true && b === false ? 1 : 0), compatible: true }

  // Across kinds
  if (aIsNum && (bIsText || bIsBool)) return { cmp: -1, compatible: true }
  if ((aIsText || aIsBool) && bIsNum) return { cmp: 1, compatible: true }
  if (aIsText && bIsBool) return { cmp: -1, compatible: true }
  if (aIsBool && bIsText) return { cmp: 1, compatible: true }

  return { cmp: 0, compatible: false }
}

/**
 * Formats a number for output
 */
function formatNumber(num) {
  if (!isFinite(num)) {
    return '#DIV/0!'
  }

  // Round to 10 significant digits
  const absNum = Math.abs(num)
  if (absNum === 0) {
    return '0'
  }

  const exp = Math.floor(Math.log10(absNum))
  const rounded = Math.round(num * Math.pow(10, 9 - exp)) / Math.pow(10, 9 - exp)

  // Format as string, removing unnecessary trailing zeros
  let str = rounded.toString()

  // Handle scientific notation edge cases
  if (str.includes('e')) {
    const parts = str.split('e')
    const mantissa = parseFloat(parts[0])
    const exponent = parseInt(parts[1], 10)
    const reconstructed = mantissa * Math.pow(10, exponent)
    return reconstructed.toString()
  }

  return str
}

/**
 * Formats a value for output
 */
function formatValue(val) {
  if (isError(val)) {
    return val
  }
  if (typeof val === 'boolean') {
    return val ? 'TRUE' : 'FALSE'
  }
  if (typeof val === 'number') {
    return formatNumber(val)
  }
  return val
}

/**
 * Expands a range into a list of addresses
 */
function expandRange(startAddr, endAddr, allCells) {
  const start = parseAddress(startAddr)
  const end = parseAddress(endAddr)

  if (!start || !end) {
    return []
  }

  const addresses = []
  const minCol = Math.min(start.col, end.col)
  const maxCol = Math.max(start.col, end.col)
  const minRow = Math.min(start.row, end.row)
  const maxRow = Math.max(start.row, end.row)

  for (let col = minCol; col <= maxCol; col++) {
    for (let row = minRow; row <= maxRow; row++) {
      // Find the address string for this cell
      let colStr = ''
      let c = col
      while (c > 0) {
        colStr = String.fromCharCode('A'.charCodeAt(0) + (c - 1) % 26) + colStr
        c = Math.floor((c - 1) / 26)
      }
      addresses.push(colStr + row)
    }
  }

  return addresses
}

/**
 * Evaluates a formula AST
 */
function evaluateAST(ast, sheet, evaluated, evaluating) {
  if (!ast) {
    return 0
  }

  if (ast.type === 'number') {
    const num = parseFloat(ast.value)
    if (!isFinite(num)) {
      return '#DIV/0!'
    }
    return num
  }

  if (ast.type === 'true') {
    return true
  }

  if (ast.type === 'false') {
    return false
  }

  if (ast.type === 'address') {
    return evaluateCell(ast.value, sheet, evaluated, evaluating)
  }

  if (ast.type === 'range') {
    // Ranges should not appear outside function arguments in valid formula
    // But if they do, we return error
    return '#ERR!'
  }

  if (ast.type === 'binop') {
    const left = evaluateAST(ast.left, sheet, evaluated, evaluating)
    if (isError(left)) {
      return left
    }

    const right = evaluateAST(ast.right, sheet, evaluated, evaluating)
    if (isError(right)) {
      return right
    }

    // Comparison operators
    if (['eq', 'ne', 'lt', 'lte', 'gt', 'gte'].includes(ast.op)) {
      const { cmp } = compareValues(left, right)

      if (ast.op === 'eq') return cmp === 0
      if (ast.op === 'ne') return cmp !== 0
      if (ast.op === 'lt') return cmp < 0
      if (ast.op === 'lte') return cmp <= 0
      if (ast.op === 'gt') return cmp > 0
      if (ast.op === 'gte') return cmp >= 0
    }

    // Arithmetic operators
    const leftNum = toNumber(left)
    if (isError(leftNum)) {
      return leftNum
    }

    const rightNum = toNumber(right)
    if (isError(rightNum)) {
      return rightNum
    }

    if (ast.op === 'plus') {
      const result = leftNum + rightNum
      return isFinite(result) ? result : '#DIV/0!'
    }
    if (ast.op === 'minus') {
      const result = leftNum - rightNum
      return isFinite(result) ? result : '#DIV/0!'
    }
    if (ast.op === 'mult') {
      const result = leftNum * rightNum
      return isFinite(result) ? result : '#DIV/0!'
    }
    if (ast.op === 'div') {
      if (rightNum === 0) {
        return '#DIV/0!'
      }
      const result = leftNum / rightNum
      return isFinite(result) ? result : '#DIV/0!'
    }
    if (ast.op === 'power') {
      const result = Math.pow(leftNum, rightNum)
      return isFinite(result) ? result : '#DIV/0!'
    }
  }

  if (ast.type === 'unop') {
    const expr = evaluateAST(ast.expr, sheet, evaluated, evaluating)
    if (isError(expr)) {
      return expr
    }

    const num = toNumber(expr)
    if (isError(num)) {
      return num
    }

    if (ast.op === 'plus') return num
    if (ast.op === 'minus') return -num
  }

  if (ast.type === 'call') {
    const name = ast.name.toUpperCase()

    // Evaluate arguments, handling ranges
    const values = []
    let firstError = null

    for (const arg of ast.args) {
      if (arg.type === 'range') {
        const addresses = expandRange(arg.start, arg.end, sheet.cells)
        for (const addr of addresses) {
          const val = evaluateCell(addr, sheet, evaluated, evaluating)
          if (isError(val) && !firstError) {
            firstError = val
          }
          values.push(val)
        }
      } else {
        const val = evaluateAST(arg, sheet, evaluated, evaluating)
        if (isError(val) && !firstError) {
          firstError = val
        }
        values.push(val)
      }
    }

    // Check argument count for functions with fixed arity
    if (name === 'ABS' && ast.args.length !== 1) {
      return '#ERR!'
    }
    if (name === 'IF' && ast.args.length !== 3) {
      return '#ERR!'
    }

    // Functions that need at least one argument
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name) && ast.args.length === 0) {
      return '#ERR!'
    }

    // Unknown function
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(name)) {
      return '#NAME?'
    }

    if (name === 'SUM') {
      if (firstError) return firstError
      let sum = 0
      for (const val of values) {
        const num = toNumber(val)
        if (isError(num)) return num
        sum += num
      }
      return sum
    }

    if (name === 'MIN') {
      if (firstError) return firstError
      let min = Infinity
      let hasNum = false
      for (const val of values) {
        const num = toNumber(val)
        if (isError(num)) return num
        hasNum = true
        if (num < min) min = num
      }
      return hasNum ? min : 0
    }

    if (name === 'MAX') {
      if (firstError) return firstError
      let max = -Infinity
      let hasNum = false
      for (const val of values) {
        const num = toNumber(val)
        if (isError(num)) return num
        hasNum = true
        if (num > max) max = num
      }
      return hasNum ? max : 0
    }

    if (name === 'COUNT') {
      if (firstError) return firstError
      let count = 0
      for (const val of values) {
        if (typeof val === 'number') {
          count++
        }
      }
      return count
    }

    if (name === 'AVG') {
      if (firstError) return firstError
      let sum = 0
      let count = 0
      for (const val of values) {
        const num = toNumber(val)
        if (isError(num)) return num
        sum += num
        count++
      }
      return count > 0 ? sum / count : 0
    }

    if (name === 'ABS') {
      if (firstError) return firstError
      const num = toNumber(values[0])
      if (isError(num)) return num
      return Math.abs(num)
    }

    if (name === 'IF') {
      // Condition is values[0], true branch is values[1], false branch is values[2]
      // We need to evaluate differently to avoid evaluating both branches
      const condition = evaluateAST(ast.args[0], sheet, evaluated, evaluating)
      if (isError(condition)) return condition

      let condBool = false
      if (typeof condition === 'boolean') {
        condBool = condition
      } else if (typeof condition === 'number') {
        condBool = condition !== 0
      }

      if (condBool) {
        return evaluateAST(ast.args[1], sheet, evaluated, evaluating)
      } else {
        return evaluateAST(ast.args[2], sheet, evaluated, evaluating)
      }
    }
  }

  return '#ERR!'
}

/**
 * Evaluates a single cell
 */
function evaluateCell(addrStr, sheet, evaluated, evaluating) {
  // Check if address is valid
  const addrInfo = parseAddress(addrStr)
  if (!addrInfo) {
    return '#REF!'
  }

  // Check for cycle
  if (evaluating.has(addrStr)) {
    return '#CYCLE!'
  }

  // Return cached result if available
  if (evaluated.has(addrStr)) {
    return evaluated.get(addrStr)
  }

  // Get cell content
  const cell = sheet.cells.get(addrStr)

  if (!cell) {
    // Undeclared cell is 0
    const result = 0
    evaluated.set(addrStr, result)
    return result
  }

  // Mark as evaluating
  evaluating.add(addrStr)

  let result

  if (cell.isFormula) {
    const ast = parseFormula(cell.content)
    if (ast === null) {
      result = '#ERR!'
    } else {
      result = evaluateAST(ast, sheet, evaluated, evaluating)
    }
  } else {
    result = parseLiteral(cell.content)
  }

  // Unmark as evaluating
  evaluating.delete(addrStr)

  // Cache result
  evaluated.set(addrStr, result)
  return result
}

/**
 * Evaluates all cells in a sheet and returns formatted output
 */
export function evaluateSheet(sheet) {
  const evaluated = new Map()
  const evaluating = new Set()

  // Sort cells by column then row
  const sorted = Array.from(sheet.cells.entries()).sort((a, b) => {
    const addrA = a[1].addr
    const addrB = b[1].addr
    if (addrA.col !== addrB.col) {
      return addrA.col - addrB.col
    }
    return addrA.row - addrB.row
  })

  const output = []
  for (const [addrStr, cell] of sorted) {
    const value = evaluateCell(addrStr, sheet, evaluated, evaluating)
    output.push(`${addrStr}=${formatValue(value)}`)
  }

  return output
}

/**
 * Gets dependencies for all cells
 */
export function getDependencies(sheet) {
  const output = []

  // Sort cells by column then row
  const sorted = Array.from(sheet.cells.entries()).sort((a, b) => {
    const addrA = a[1].addr
    const addrB = b[1].addr
    if (addrA.col !== addrB.col) {
      return addrA.col - addrB.col
    }
    return addrA.row - addrB.row
  })

  for (const [addrStr, cell] of sorted) {
    let deps = []

    if (cell.isFormula) {
      const ast = parseFormula(cell.content)
      if (ast !== null) {
        deps = extractAddresses(ast)

        // Filter to only valid addresses and remove duplicates
        const validDeps = new Set()
        for (const dep of deps) {
          const depInfo = parseAddress(dep)
          if (depInfo) {
            validDeps.add(dep)
          }
        }

        // Sort deps by column then row
        deps = Array.from(validDeps).sort((a, b) => {
          const addrA = parseAddress(a)
          const addrB = parseAddress(b)
          if (addrA.col !== addrB.col) {
            return addrA.col - addrB.col
          }
          return addrA.row - addrB.row
        })
      }
    }

    if (deps.length > 0) {
      output.push(`${addrStr}: ${deps.join(' ')}`)
    } else {
      output.push(`${addrStr}:`)
    }
  }

  return output
}

