/**
 * Evaluation of cell values and of the cells a formula names.
 */

import { parseAddress, numToCol, parseFormulaBody } from './parser.js'

const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

function err(token) {
  return { kind: 'error', token }
}

const DIV0 = err('#DIV/0!')
const VALUE = err('#VALUE!')
const REF = err('#REF!')
const CYCLE = err('#CYCLE!')
const ERR = err('#ERR!')
const NAME = err('#NAME?')

function num(n) {
  return { kind: 'number', value: n }
}

function text(s) {
  return { kind: 'text', value: s }
}

function bool(b) {
  return { kind: 'boolean', value: b }
}

function isErr(v) {
  return v.kind === 'error'
}

function finite(n) {
  return Number.isFinite(n) ? num(n) : DIV0
}

/* ------------------------------------------------------------------ */
/* Literals                                                            */
/* ------------------------------------------------------------------ */

function parseLiteral(content) {
  if (content === '') return num(0)
  if (ERROR_TOKENS.includes(content)) return err(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(parseFloat(content))
  return text(content)
}

/* ------------------------------------------------------------------ */
/* Coercion and comparison                                             */
/* ------------------------------------------------------------------ */

function toNumber(v) {
  if (v.kind === 'number') return v
  if (v.kind === 'boolean') return num(v.value ? 1 : 0)
  if (v.kind === 'error') return v
  return VALUE
}

function rank(v) {
  if (v.kind === 'number') return 0
  if (v.kind === 'text') return 1
  return 2
}

function compareText(a, b) {
  const as = Array.from(a)
  const bs = Array.from(b)
  const n = Math.min(as.length, bs.length)
  for (let i = 0; i < n; i++) {
    const x = as[i].codePointAt(0)
    const y = bs[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (as.length === bs.length) return 0
  return as.length < bs.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (ra === 1) return compareText(a.value, b.value)
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

/* ------------------------------------------------------------------ */
/* Formatting                                                          */
/* ------------------------------------------------------------------ */

function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(v) {
  if (v.kind === 'error') return v.token
  if (v.kind === 'boolean') return v.value ? 'TRUE' : 'FALSE'
  if (v.kind === 'number') return formatNumber(v.value)
  return v.value
}

/* ------------------------------------------------------------------ */
/* Ranges                                                              */
/* ------------------------------------------------------------------ */

function expandRange(startName, endName) {
  const a = parseAddress(startName)
  const b = parseAddress(endName)
  if (!a || !b) return null
  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const out = []
  for (let c = minCol; c <= maxCol; c++) {
    const colName = numToCol(c)
    for (let r = minRow; r <= maxRow; r++) out.push(colName + r)
  }
  return out
}

/* ------------------------------------------------------------------ */
/* Evaluation                                                          */
/* ------------------------------------------------------------------ */

export class Engine {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.active = new Set()
  }

  valueOf(addrName) {
    if (!parseAddress(addrName)) return REF
    if (this.active.has(addrName)) return CYCLE
    if (this.cache.has(addrName)) return this.cache.get(addrName)

    const cell = this.cells.get(addrName)
    if (!cell) {
      const v = num(0)
      this.cache.set(addrName, v)
      return v
    }

    this.active.add(addrName)
    let result
    if (cell.content.startsWith('=')) {
      const ast = parseFormulaBody(cell.content.slice(1))
      result = ast === null ? ERR : this.evalNode(ast)
    } else {
      result = parseLiteral(cell.content)
    }
    this.active.delete(addrName)
    this.cache.set(addrName, result)
    return result
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return finite(node.value)
      case 'boolean':
        return bool(node.value)
      case 'ref':
        return this.valueOf(node.name)
      case 'range':
        return ERR
      case 'unop': {
        const v = this.evalNode(node.operand)
        if (isErr(v)) return v
        const n = toNumber(v)
        if (isErr(n)) return n
        return node.op === '-' ? finite(-n.value) : finite(n.value)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        return ERR
    }
  }

  evalBinop(node) {
    const left = this.evalNode(node.left)
    if (isErr(left)) return left
    const right = this.evalNode(node.right)
    if (isErr(right)) return right

    switch (node.op) {
      case '=':
        return bool(compare(left, right) === 0)
      case '<>':
        return bool(compare(left, right) !== 0)
      case '<':
        return bool(compare(left, right) < 0)
      case '<=':
        return bool(compare(left, right) <= 0)
      case '>':
        return bool(compare(left, right) > 0)
      case '>=':
        return bool(compare(left, right) >= 0)
      default:
        break
    }

    const a = toNumber(left)
    if (isErr(a)) return a
    const b = toNumber(right)
    if (isErr(b)) return b

    switch (node.op) {
      case '+':
        return finite(a.value + b.value)
      case '-':
        return finite(a.value - b.value)
      case '*':
        return finite(a.value * b.value)
      case '/':
        if (b.value === 0) return DIV0
        return finite(a.value / b.value)
      case '^':
        return finite(Math.pow(a.value, b.value))
      default:
        return ERR
    }
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.has(name)) return NAME

    const argc = node.args.length
    if (name === 'ABS' && argc !== 1) return ERR
    if (name === 'IF' && argc !== 3) return ERR
    if (name !== 'ABS' && name !== 'IF' && argc < 1) return ERR

    if (name === 'IF') {
      const cond = this.evalNode(node.args[0])
      if (isErr(cond)) return cond
      let truth
      if (cond.kind === 'boolean') truth = cond.value
      else if (cond.kind === 'number') truth = cond.value !== 0
      else return VALUE
      return this.evalNode(truth ? node.args[1] : node.args[2])
    }

    const values = []
    for (const arg of node.args) {
      if (arg.type === 'range' && !arg.misplaced) {
        const addrs = expandRange(arg.start, arg.end)
        if (addrs === null) {
          values.push(REF)
        } else {
          for (const a of addrs) values.push(this.valueOf(a))
        }
      } else {
        values.push(this.evalNode(arg))
      }
    }

    for (const v of values) {
      if (isErr(v)) return v
    }

    if (name === 'COUNT') {
      let count = 0
      for (const v of values) if (v.kind === 'number') count++
      return num(count)
    }

    const numbers = []
    for (const v of values) {
      const n = toNumber(v)
      if (isErr(n)) return n
      numbers.push(n.value)
    }

    switch (name) {
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      case 'SUM': {
        let s = 0
        for (const n of numbers) s += n
        return finite(s)
      }
      case 'MIN': {
        let m = numbers[0]
        for (const n of numbers) if (n < m) m = n
        return finite(m)
      }
      case 'MAX': {
        let m = numbers[0]
        for (const n of numbers) if (n > m) m = n
        return finite(m)
      }
      case 'AVG': {
        let s = 0
        for (const n of numbers) s += n
        if (numbers.length === 0) return DIV0
        return finite(s / numbers.length)
      }
      default:
        return ERR
    }
  }
}

/* ------------------------------------------------------------------ */
/* Dependencies                                                        */
/* ------------------------------------------------------------------ */

function collectRefs(node, out) {
  if (!node) return
  switch (node.type) {
    case 'ref':
      out.push(node.name)
      break
    case 'range': {
      const addrs = expandRange(node.start, node.end)
      if (addrs !== null) for (const a of addrs) out.push(a)
      break
    }
    case 'unop':
      collectRefs(node.operand, out)
      break
    case 'binop':
      collectRefs(node.left, out)
      collectRefs(node.right, out)
      break
    case 'call':
      for (const arg of node.args) collectRefs(arg, out)
      break
    default:
      break
  }
}

function sortAddresses(names) {
  return names.sort((x, y) => {
    const a = parseAddress(x)
    const b = parseAddress(y)
    if (a.col !== b.col) return a.col - b.col
    return a.row - b.row
  })
}

export function depsOf(content) {
  if (!content.startsWith('=')) return []
  const ast = parseFormulaBody(content.slice(1))
  if (ast === null) return []
  const refs = []
  collectRefs(ast, refs)
  const seen = new Set()
  for (const r of refs) {
    if (parseAddress(r)) seen.add(r)
  }
  return sortAddresses(Array.from(seen))
}

export function sortedCells(cells) {
  return Array.from(cells.entries()).sort((a, b) => {
    if (a[1].col !== b[1].col) return a[1].col - b[1].col
    return a[1].row - b[1].row
  })
}

